pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        vm.assume(receiver != address(c));
        vm.assume(receiver.balance < type(uint256).max - amount);

        uint256 balanceBefore = address(c).balance;
        vm.prank(c.owner());
        c.sendTo(receiver, amount);
        uint256 balanceAfter = address(c).balance;

        assertTrue(balanceBefore - balanceAfter == amount);
    }
