pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0) && receiver != address(this));
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.deal(address(this), amount + 1 ether);
        uint256 before = receiver.balance;
        c.sendTo(receiver, amount);
        uint256 after = receiver.balance;
        assertTrue(after - before == amount, "Receiver should receive exactly the amount sent");
    }
}

